package com.hsm.common;
import jakarta.validation.ConstraintViolationException; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ApiException.class) ResponseEntity<?> api(ApiException e){return ResponseEntity.status(e.getStatus()).body(Map.of("error",e.getCode(),"message",e.getMessage()));} @ExceptionHandler({MethodArgumentNotValidException.class,ConstraintViolationException.class}) ResponseEntity<?> validation(Exception e){return ResponseEntity.badRequest().body(Map.of("error","VALIDATION_ERROR","message","Request validation failed."));} @ExceptionHandler(Exception.class) ResponseEntity<?> other(){return ResponseEntity.internalServerError().body(Map.of("error","INTERNAL_ERROR","message","An unexpected error occurred."));} }
